186: function tickWalk(dt) {
187:   const p = playerPosition();
188:   if (movementStick.active) {
189:     const length = Math.hypot(movementStick.x, movementStick.y) || 1;
190:     const speed = 0.14 * dt * Math.min(1, length);
191:     const bounds = walkBounds[game.place] || { minY: 20, maxY: 350 };
192:     p.x = Math.max(0, Math.min(W, p.x + movementStick.x / length * speed));
193:     p.y = Math.max(bounds.minY, Math.min(bounds.maxY, p.y + movementStick.y / length * speed));
194:     p.walking = true;
195:     if (movementStick.x) p.face = movementStick.x < 0 ? -1 : 1;
196:     if (tryEnterWorldRoute()) return;
197:     return;
198:   }
199:   if (p.tx == null) { p.walking = false; return; }
200:   const dx = p.tx - p.x, dy = p.ty - p.y;
201:   const d = Math.hypot(dx, dy);
202:   const step = Math.min(0.18 * dt, d);
203:   if (d < 1.5) {
204:     p.x = p.tx; p.y = p.ty;
205:     delete p.tx; delete p.ty;
206:     p.walking = false;
207:     if (tryEnterWorldRoute()) return;
208:     if (p.auto) { delete p.auto; interact(); }
209:     save();
210:     return;
211:   }
212:   p.x += dx / d * step;
213:   p.y += dy / d * step;
214:   p.walking = true;
215:   if (Math.abs(dx) > 1) p.face = dx < 0 ? -1 : 1;
216:   tryEnterWorldRoute();
217: }
